import type { Tools } from "../generated/tools";

export default async function flow(
  input: { issueKey: string },
  tools: Tools
) {
  let attempt = 0;
  let issue: Issue | null = null;

  while (issue === null && attempt < 3) {
    attempt += 1;
    try {
      const fetched = await tools.jira.getIssue({ key: input.issueKey });
      issue = fetched;
    } catch {
      // Issue service is flaky — fall through and retry up to the attempt limit.
    }
  }

  if (issue === null) {
    await tools.slack.send({
      channel: "#ops",
      message: `Could not fetch issue ${input.issueKey} after ${attempt} attempts.`
    });
    return { fetched: false, transitioned: false };
  }

  await tools.jira.transitionIssue({ key: input.issueKey, status: "In Review" });

  return { fetched: true, transitioned: true };
}

