import type { Tools } from "../generated/tools";
import { formatDigest } from "@flows/lib";

export default async function flow(
  input: { repository: string; jql: string; recipient: string },
  tools: Tools
) {
  const [stats, issues, activity] = await Promise.all([
    tools.github.getRepoStats({ repo: input.repository }),
    tools.jira.searchIssues({ jql: input.jql }),
    tools.slack.getChannelActivity({ channel: "#engineering" })
  ]);

  const digest = formatDigest(stats, issues, activity);

  await tools.email.send({
    to: input.recipient,
    subject: `Weekly digest: ${input.repository}`,
    body: digest
  });

  return { delivered: true };
}

