import type { Tools } from "../generated/tools";
import { severityOf } from "@flows/lib";

export default async function flow(
  input: { issueKey: string },
  tools: Tools
) {
  const issue = await tools.jira.getIssue({ key: input.issueKey });
  const severity = severityOf(issue);

  if (severity === "critical") {
    const followUp = await tools.jira.createIssue({
      project: "OPS",
      summary: `Follow-up: ${issue.summary}`,
      description: `Auto-created follow-up for critical issue ${issue.key}.`,
    });
    await tools.slack.send({
      channel: "#incidents",
      message: `Critical issue ${issue.key}: follow-up ${followUp.key} created in OPS.`,
    });
  } else if (severity === "high") {
    await tools.slack.send({
      channel: "#engineering",
      message: `High severity issue ${issue.key} needs attention.`,
    });
  }

  return { severity };
}

import type { Tools } from "../generated/tools";
import { severityOf } from "@flows/lib";

export default async function flow(
  input: { issueKey: string },
  tools: Tools
) {
  let issue = null;

  try {
    const fetched = await tools.jira.getIssue({ key: input.issueKey });
    issue = fetched;
  } catch (error) {
    await tools.slack.send({
      channel: "#incidents",
      message: `Failed to fetch issue ${input.issueKey}: ${String(error)}`
    });
    return { severity: null };
  }

  const severity = severityOf(issue);

  if (severity === "critical") {
    const followUp = await tools.jira.createIssue({
      project: "OPS",
      summary: `Follow-up for ${input.issueKey}`,
      description: `Automatically created follow-up for critical issue ${input.issueKey}.`
    });
    await tools.slack.send({
      channel: "#incidents",
      message: `Critical issue ${input.issueKey} — follow-up ${followUp.key} created in OPS.`
    });
  } else if (severity === "high") {
    await tools.slack.send({
      channel: "#engineering",
      message: `High severity issue ${input.issueKey} needs attention.`
    });
  }

  return { severity };
}

import type { Tools } from "../generated/tools";

function auditMessage(delivered: boolean): string {
  return delivered
    ? "Release note delivered to #releases."
    : "Release note NOT delivered to #releases; on-call has been alerted.";
}

export default async function flow(
  input: { releaseNote: string; onCallAddress: string },
  tools: Tools
) {
  let delivered = false;

  try {
    await tools.slack.send({ channel: "#releases", message: input.releaseNote });
    delivered = true;
  } catch (error) {
    await tools.email.send({
      to: input.onCallAddress,
      subject: "Release note delivery failed",
      body: `Could not post the release note to #releases: ${String(error)}`
    });
  }

  await tools.slack.send({ channel: "#audit", message: auditMessage(delivered) });

  return { delivered };
}

