import type { Tools } from "../generated/tools";

function isWip(pr: PullRequest): boolean {
  return pr.title.startsWith("WIP");
}

export default async function flow(
  input: { repository: string },
  tools: Tools
) {
  const prs = await tools.github.getNewPRs({ repo: input.repository });

  let commentsPosted = 0;

  for (const pr of prs) {
    if (commentsPosted >= 5) {
      break;
    }

    if (isWip(pr)) {
      continue;
    }

    const body = `Queued for review: ${pr.title}`;
    await tools.github.addComment({ pr, body });
    commentsPosted += 1;
  }

  return { commentsPosted };
}

import type { Tools } from "../generated/tools";

function isWip(pr: { title: string }): boolean {
  return pr.title.startsWith("WIP");
}

export default async function flow(
  input: { repository: string },
  tools: Tools
) {
  const pullRequests = await tools.github.getNewPRs({ repo: input.repository });

  let posted = 0;

  for (const pr of pullRequests) {
    if (posted >= 5) {
      break;
    }

    if (isWip(pr)) {
      continue;
    }

    await tools.github.addComment({
      pr,
      body: `Queued for review: ${pr.title}`,
    });

    posted += 1;
  }

  return { queuedForReview: posted };
}
